import { okResult, type CliCommandResult } from '../envelope';
import type { CliIO } from '../io';
import { requestServer } from '../client';
import { withCallerSessionModel } from '../callerModel';
import {
  withHostWorkNextAction,
  type StatusWithHostWork,
} from '../hostWorkNextAction';
import {
  serverVersionInfo,
  staleWarningLine,
  versionEnvelopeFields,
} from '../serverVersion';
import {
  attachOrUnavailable,
  isAttached,
  isCommandResult,
  parseCommandContext,
  serverErrorResult,
  transportErrorResult,
} from './shared';

const COMMAND = 'status';
const WATCH_POLL_INTERVAL_MS = 1_000;

const STATUS_FLAG_SPEC = {
  watch: { takesValue: false },
};

const sleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

export const handleStatus = async (
  args: string[],
  io: CliIO,
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args, STATUS_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }

  const attached = await attachOrUnavailable(COMMAND, context.projectPath);
  if (!isAttached(attached)) {
    return attached;
  }

  const versionInfo = serverVersionInfo(attached.handshake);
  if (versionInfo.staleServer) {
    io.writeProgress(
      `${staleWarningLine(versionInfo)} Run \`rivet open\` to restart it and retry interrupted work.`,
    );
  }

  const fetchStatus = async (): Promise<CliCommandResult> => {
    try {
      const response = await requestServer<StatusWithHostWork>(
        attached,
        '/api/cli/status',
      );
      if (response.status !== 200) {
        return serverErrorResult(COMMAND, response.status, response.body);
      }
      const handoff = await withCallerSessionModel(context.handoff);
      return okResult(COMMAND, {
        ...withHostWorkNextAction(response.body, {
          callerAgent: handoff?.agent,
          callerModel: handoff?.model,
        }),
        ...versionEnvelopeFields(attached.handshake),
      });
    } catch (error) {
      return transportErrorResult(COMMAND, error);
    }
  };

  if (context.flags.values.watch !== true) {
    return fetchStatus();
  }

  let lastSerialized: string | null = null;
  for (;;) {
    const result = await fetchStatus();
    if (!result.envelope.ok) {
      return result;
    }
    const serialized = JSON.stringify(result.envelope);
    if (serialized !== lastSerialized) {
      io.writeEnvelope(result.envelope);
      lastSerialized = serialized;
    }
    await sleep(WATCH_POLL_INTERVAL_MS);
  }
};
